sql.content:

if not exists(
    select id from att_schetransaction 
    where employee_id = '%(employee_id)s' and att_date= '%(att_date)s' and
    punch_time= '%(punch_time)s'
)
INSERT INTO att_schetransaction(
    employee_id, punch_time, punch_state, correct_state, transaction_id,
    tid, op, att_date
) 
VALUES ('%(employee_id)s', '%(punch_time)s', '%(punch_state)s', '%(correct_state)s',
    '%(transaction_id)s', %(tid)s, '%(op)s', '%(att_date)s'
)


if not exists(
    select id from att_multipletransaction
    where employee_id = %(employee_id)s and data_type = %(data_type)s
    and att_date = '%(att_date)s' and timetable= %(timetable)s and data_index= %(data_index)s
)
INSERT INTO att_multipletransaction(
    employee_id, data_type, att_date, timetable, data_index, in_time, in_transaction,
    out_time, out_transaction, total_time, worked_time
)
VALUES ( %(employee_id)s, %(data_type)s, '%(att_date)s', %(timetable)s, 
    %(data_index)s, '%(in_time)s', %(in_transaction)s, '%(out_time)s', 
    %(out_transaction)s, %(total_time)s, %(worked_time)s
)
